package com.complex.platform.dealer;

// 文件版本：V0.01

import com.complex.platform.dealer.dto.DealerDeliveryReceiptRequest;
import com.complex.platform.evidence.EvidenceEventService;
import java.time.Instant;
import java.util.List;
import java.util.UUID;

final class DealerTestDeliveries {
    static org.springframework.mock.web.MockMultipartFile file() {
        return new org.springframework.mock.web.MockMultipartFile("file","真实签收凭证.png","image/png",java.util.Base64.getDecoder().decode(
                "iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mP8/x8AAwMCAO+jz1sAAAAASUVORK5CYII="));
    }
    static org.springframework.mock.web.MockMultipartFile video() {
        return new org.springframework.mock.web.MockMultipartFile("file","实际处置录像.mp4","video/mp4",java.util.Base64.getDecoder().decode(""));
    }
    static String proof(EvidenceEventService evidence,String orderId) {return evidence.uploadAttachment(file(),"dealer_delivery",orderId,"other").id();}
    static DealerDeliveryReceiptRequest full(String orderId,List<DealerOrderLineRecord> lines,String proof) {
        return new DealerDeliveryReceiptRequest(UUID.randomUUID().toString(),orderId,Instant.now(),"已核验的合同收货联系人",List.of(proof),
                lines.stream().map(l->new DealerDeliveryReceiptRequest.Line(l.id(),l.quantity(),0,0,0)).toList(),"逐项核对实际全量签收");
    }
}
